export const acquire = Effect.fn("MaestroAtlasToolV2.acquire")(function* (
  services: MaestroAtlasSourceV2.Services,
  placement: MaestroAtlasSourceV2.Placement,
  ids: readonly string[],
) {
  const before = yield* MaestroAtlasSourceV2.read(services, placement)
  const units = yield* Effect.forEach(
    ids,
    Effect.fnUntraced(function* (id) {
      const unit = yield* MaestroAtlasSourceV2.unit(services, placement, id)
      if (
        unit.projectID !== placement.projectID ||
        unit.unit !== id ||
        unit.sourceIdentity !== before.identityHash ||
        unit.sourceRevision !== before.context.sourceRevision ||
        unit.receipt.sourceRevision !== unit.sourceRevision ||
        unit.coverage.state !== "complete" ||
        unit.coverage.freshness !== "FRESH" ||
        unit.coverage.truncated !== false
      )
        return yield* held("unit-acquisition-mismatch", [id])
      return {
        unit: unit.unit,
        name: unit.name,
        sourceIdentity: unit.sourceIdentity,
        sourceRevision: unit.receipt.sourceRevision,
        contentHash: unit.contentHash,
        receiptHash: unit.receiptHash,
        bodyHash: digest(unit.content),
        content: unit.content,
      } satisfies AtlasKnowledge.Unit
    }),
  )
  if (units.reduce((bytes, unit) => bytes + Buffer.byteLength(unit.content, "utf8"), 0) > AtlasKnowledge.MAX_BYTES)
    return yield* held("knowledge-body-budget-exceeded", ids)
  const after = yield* MaestroAtlasSourceV2.read(services, placement)
  if (after.identityHash !== before.identityHash || after.directory !== before.directory)
    return yield* held("source-changed-during-anchor", [before.identityHash, after.identityHash])
  return units

export function owner(id: string, seats: MaestroSeats.Interface): Owner | undefined {
  if (!seats.has(id) || Seats.all[id]?.atlasMemory !== true) return undefined
  return id === "backend" || id === "jimmy" || id === "archie" || id === "live" ? id : undefined
}

/** Atlas context reads (catalog, unit) also reach Maestro; anchor and the memory tools stay with the seats. */
export function reader(id: string, seats: MaestroSeats.Interface): Owner | "maestro" | undefined {
  if (id === AgentV2.defaultID) return "maestro"
  return owner(id, seats)

/** Bounded unit and territory metadata of the verified Own catalog; bodies are never loaded. */
export const catalog = Effect.fn("MaestroAtlasV2.catalog")(function* (services: Services, placement: Placement) {
  const source = yield* read(services, placement)
  const units = boundedRows(
    source.context.units.map((unit) => ({
      unit: unit.unit,
      skillName: unit.skillName,
      graphCoverage: unit.receipt.graphCoverage,
      tokenEstimate: unit.tokenEstimate,
      complete: complete(unit),
    })),
  )
  const territories = boundedRows(
    source.context.territories.map((territory) => ({
      name: territory.name,
      owner: territory.owner,
      tier: territory.tier,
      globs: territory.globs,
    })),
  )
  return {
    projectID: placement.projectID,
    sourceIdentity: source.identityHash,
    sourceRevision: source.context.sourceRevision,
    catalogVersion: source.context.catalogVersion,
    units,
    territories,
    coverage: {
      state:
        units.length === source.context.units.length && territories.length === source.context.territories.length
          ? ("complete" as const)
          : ("partial" as const),
      scope: "verified-own-catalog" as const,
      units: { returned: units.length, total: source.context.units.length },
      territories: { returned: territories.length, total: source.context.territories.length },
      bodiesLoaded: false,
    },
  }
})

